// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;

    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount >= 10 ether);
        Attacker attacker = new Attacker(c);
        vm.deal(address(c), amount);
        c.getFirstWithdrawalBonus(address(attacker));
        // Rule: only one 100-wei bonus may ever leave c for this recipient;
        // the reentrancy guard blocks the nested payout in the reference.
        assertTrue(address(c).balance == amount - 100);
    }
}

contract Attacker {
    Reentrancy_bonus c;
    constructor(Reentrancy_bonus _c) { c = _c; }
    receive() external payable {
        try c.getFirstWithdrawalBonus(address(this)) {} catch {}
    }
}
